63	            return ApiResponse.error(404, "挂载配置不存在");
64	        }
65	        String username = auth.getName();
66	        Map<String, Object> result = mountService.executeUnmount(id, username);
67	        return ApiResponse.success("卸载执行完成", result);
68	    }
69	
70	    @GetMapping("/api/mounts/{id}/logs")
