}

public List<CacheMount> listMounts(Long clusterId) {
    return cacheMountMapper.findByClusterId(clusterId);
}

public CacheMount getMount(Long id) {
    return cacheMountMapper.findById(id);
}

public Map<String, Object> executeMount(Long mountId, String username) {
    CacheMount mount = cacheMountMapper.findById(mountId);
    User user = userMapper.findByUsername(username);
    String mountOptions = mount.getMountOptions() != null ? mount.getMountOptions() : "defaults";
    Map<String, Object> result = runCommand(mountId, user, "MOUNT",
            "mount", "-t", mount.getFsType(), "-o", mountOptions,
            mount.getSourcePath(), mount.getTargetPath());
    int exitCode = (Integer) result.get("exitCode");
    cacheMountMapper.updateStatus(mountId, exitCode == 0 ? "MOUNTED" : "FAILED", LocalDateTime.now());
    return result;
}

public Map<String, Object> executeUnmount(Long mountId, String username) {
    CacheMount mount = cacheMountMapper.findById(mountId);
    User user = userMapper.findByUsername(username);
    Map<String, Object> result = runCommand(mountId, user, "UNMOUNT",
            "umount", mount.getTargetPath());
    int exitCode = (Integer) result.get("exitCode");
    if (exitCode == 0) {
        cacheMountMapper.updateStatus(mountId, "PENDING", LocalDateTime.now());
    }
    return result;
}

private Map<String, Object> runCommand(Long mountId, User user, String operation, String... command) {
    String commandOutput;
    int exitCode;
    try {
        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true);
        Process process = processBuilder.start();
        commandOutput = readProcessOutput(process);
        exitCode = process.waitFor();
    } catch (Exception e) {
        commandOutput = e.getMessage() != null ? e.getMessage() : "Command execution failed";
        exitCode = -1;
    }

    String status = exitCode == 0 ? "SUCCESS" : "FAILED";

    MountLog mountLog = new MountLog();
    mountLog.setMountId(mountId);
    mountLog.setUserId(user.getId());
    mountLog.setOperation(operation);
    mountLog.setCommandOutput(commandOutput);
    mountLog.setExitCode(exitCode);
    mountLog.setStatus(status);
    mountLog.setCreatedAt(LocalDateTime.now());
    mountLogMapper.insert(mountLog);

